package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import java.io.StringWriter;
import java.io.IOException;
import static org.junit.Assert.*;

public class AgentBRT_Lang_19_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        NumericEntityUnescaper unescaper = new NumericEntityUnescaper();
        StringWriter writer = new StringWriter();
        String input = "Test &#65 without semicolon"; // &#65 is 'A' in ASCII

        try {
            int result = unescaper.translate(input, 5, writer);
            assertEquals("Expected translation length to be 0 due to missing semicolon", 0, result);
            assertEquals("Expected no translation due to missing semicolon", "Test &#65 without semicolon", writer.toString());
        } catch (IOException e) {
            fail("IOException should not occur");
        }
    }
}

